
-- Stabilize VÉRIX Admin dashboard cache under database load.
-- The Admin sends current snapshots with p_now generated by the Edge Function.
-- A delayed request must not bypass the shared cache merely because it waited
-- more than ten seconds before PostgreSQL began executing it. Keep historical
-- requests older than one hour on the uncached path, but let recent requests
-- use the shared cache despite transient delays.
DO $admin_cache_stability$
DECLARE
  r record;
  v_def text;
  v_old_live text;
  v_new_live text;
  v_old_ttl text := 'interval ''6 minutes''';
  v_new_ttl text := 'interval ''10 minutes''';
  v_hits integer;
BEGIN
  FOR r IN
    SELECT p.proname, p.oid
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN ('verix2_admin_dashboard_v3', 'verix2_admin_dashboard_cached')
      AND pg_get_function_identity_arguments(p.oid) =
        'p_now timestamp with time zone, p_force_refresh boolean'
    ORDER BY p.proname
  LOOP
    v_def := pg_get_functiondef(r.oid);

    IF r.proname = 'verix2_admin_dashboard_v3' THEN
      v_old_live := 'v_is_live := abs(extract(epoch FROM (v_now - clock_timestamp()))) <= 10;';
      v_new_live := 'v_is_live := abs(extract(epoch FROM (v_now - clock_timestamp()))) <= 3600;';
    ELSE
      v_old_live := 'v_live := abs(extract(epoch FROM (v_now - clock_timestamp()))) <= 10;';
      v_new_live := 'v_live := abs(extract(epoch FROM (v_now - clock_timestamp()))) <= 3600;';
    END IF;

    v_hits := (length(v_def) - length(replace(v_def, v_old_live, ''))) / length(v_old_live);
    IF v_hits <> 1 THEN
      RAISE EXCEPTION 'Expected exactly one live-window marker in %, found %', r.proname, v_hits;
    END IF;
    v_def := replace(v_def, v_old_live, v_new_live);

    v_hits := (length(v_def) - length(replace(v_def, v_old_ttl, ''))) / length(v_old_ttl);
    IF v_hits <> 2 THEN
      RAISE EXCEPTION 'Expected exactly two cache TTL markers in %, found %', r.proname, v_hits;
    END IF;
    v_def := replace(v_def, v_old_ttl, v_new_ttl);

    EXECUTE v_def;
  END LOOP;
END
$admin_cache_stability$;
